 import React, { useState } from 'react';
import { Link, useNavigate } from 'react-router-dom';
import './Login.css';
import HomeIcon from '../Common/HomeIcon';
import { login } from '../../services/api'; // Asigurați-vă că importați funcția login

function Login() {
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [submitted, setSubmitted] = useState(false);
  const [error, setError] = useState(null);

  const navigate = useNavigate();

  const handleSubmit = async (e) => {
    e.preventDefault();

    if (!email || !password) {
      alert('Completează toate câmpurile!');
      return;
    }

    try {
      // Așteptăm rezultatul de la apelul API de login
      const result = await login({ email, password });

      // --- SALVARE DATE ÎN LOCAL STORAGE ---
      // !!! IMPORTANT: Ajustați câmpurile 'result.token', 'result.userId', etc.
      // conform structurii REALE a obiectului returnat de backend la login cu succes. !!!

      // Salvează token-ul JWT
      // Presupunem că token-ul este în result.token
      if (result && result.token) {
         localStorage.setItem('token', result.token);
      } else {
          // Dacă token-ul nu e găsit în răspuns, tratează ca eroare
          throw new Error(result && result.message ? result.message : 'Login successful but token not received.');
      }


      // Salvează ID-ul utilizatorului logat
      // Presupunem că ID-ul utilizatorului este în result.userId
      // VERIFICATI CU ATENTIE structura răspunsului backend!
      if (result.userId !== undefined && result.userId !== null) {
           localStorage.setItem('userId', result.userId);
      } else if (result.user && result.user.id !== undefined && result.user.id !== null) {
           // Alternativ, dacă ID-ul este într-un sub-obiect user:
           localStorage.setItem('userId', result.user.id);
      }
       else {
           console.warn("User ID not found in login response. Delete functionality may not work.");
           // Opțional: elimină userId vechi dacă nu s-a putut citi noul
           localStorage.removeItem('userId');
       }


      // Salvează username (folosește din răspuns dacă există, altfel extrage din email)
      localStorage.setItem('username', result.username || email.split('@')[0]);

      // Salvează email-ul (folosește din răspuns dacă există, altfel din input)
      localStorage.setItem('email', result.email || email);
      // --- SFÂRȘIT SALVARE ---


      // Notifică aplicația că s-a schimbat autentificarea
      window.dispatchEvent(new Event('authChange'));

      // Redirecționează către pagina principală
      navigate('/', { replace: true });

    } catch (err) {
      // Gestionarea erorilor (afișează mesajul din backend sau o eroare implicită)
      const errorMessage = err.message || 'A apărut o eroare la autentificare.';
      setError(errorMessage);
      alert(errorMessage);
    }
  };

  return (
    <div className="login-container">
      <HomeIcon />
      <h1>Login</h1>

      <form onSubmit={handleSubmit}>
        <input
          type="email"
          placeholder="Email"
          value={email}
          onChange={(e) => setEmail(e.target.value)}
          required // Adaugă atributul required pentru validare HTML5
        />
        <input
          type="password"
          placeholder="Parolă"
          value={password}
          onChange={(e) => setPassword(e.target.value)}
          required // Adaugă atributul required pentru validare HTML5
        />
        <button type="submit">Login</button>

        {/* Afișează eroarea dacă există */}
        {error && <p style={{ color: 'red' }}>{error}</p>}

        <p style={{ textAlign: 'center', marginTop: '15px' }}>
          Nu ai un cont? <Link to="/register">Înregistrează-te</Link>
        </p>
      </form>

      {/* submitted && <p style={{ color: 'green' }}>Te-ai logat cu succes!</p> */}
      {/* Acest mesaj "Te-ai logat cu succes!" nu va fi afișat, deoarece navigăm imediat.
          Puteți să îl lăsați sau să îl ștergeți. */}
    </div>
  );
}

export default Login;
